SQL_DOC.P_SQL:
DECLARE V_CNT NUMBER; BEGIN SELECT COUNT(*) INTO V_CNT FROM TBL_KEP_DS WHERE LEGACY_PO_NO = $LEGACY_PO_NO$ AND LEGACY_PO_SEQ = $LEGACY_PO_SEQ$ AND DS_SEQ = $DS_SEQ$ ;
IF V_CNT = 0 THEN INSERT INTO TBL_KEP_DS( LEGACY_PO_NO , LEGACY_PO_SEQ , DS_SEQ , DS_DATE , DS_QTY , ADD_DATE , PICODE , PISTAT ) VALUES ( $LEGACY_PO_NO$ , $LEGACY_PO_SEQ$ , $DS_SEQ$ , $DS_DATE$ , $DS_QTY$ , $ADD_DATE$ , 'HID_MM_IF062' , 'R' ); END IF;
END;
